CREATE TABLE IF NOT EXISTS organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(120) NOT NULL,slug varchar(80) NOT NULL UNIQUE,status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('TRIAL','ACTIVE','PAST_DUE','SUSPENDED','CANCELED')),plan varchar(30) NOT NULL DEFAULT 'STARTER',trial_ends_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS organization_members(organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,role user_role NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,user_id));
INSERT INTO organizations(name,slug,status,plan) VALUES('Navalha Barber Club','navalha','ACTIVE','PRO') ON CONFLICT(slug) DO NOTHING;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['barbers','clients','services','appointments','payments','business_settings','business_hours','schedule_blocks','message_queue','commission_closures','appointment_audit'] LOOP EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS organization_id uuid REFERENCES organizations(id)',t);EXECUTE format('UPDATE %I SET organization_id=(SELECT id FROM organizations WHERE slug=''navalha'') WHERE organization_id IS NULL',t);EXECUTE format('ALTER TABLE %I ALTER COLUMN organization_id SET NOT NULL',t);END LOOP;END $$;
INSERT INTO organization_members(organization_id,user_id,role) SELECT o.id,u.id,u.role FROM organizations o CROSS JOIN users u WHERE o.slug='navalha' ON CONFLICT DO NOTHING;
ALTER TABLE services DROP CONSTRAINT IF EXISTS services_name_key;
CREATE UNIQUE INDEX IF NOT EXISTS services_org_name_key ON services(organization_id,lower(name));
CREATE INDEX IF NOT EXISTS clients_org_idx ON clients(organization_id,name);CREATE INDEX IF NOT EXISTS appointments_org_time_idx ON appointments(organization_id,starts_at);CREATE INDEX IF NOT EXISTS payments_org_time_idx ON payments(organization_id,paid_at);CREATE INDEX IF NOT EXISTS barbers_org_idx ON barbers(organization_id,active);
